```python
def facteur(n):
    if n < 0:
        raise ValueError("n must be >= 0")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result
```

```python
def tri_bulles(l):
    n = len(l)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if l[j] > l[j + 1]:
                l[j], l[j + 1] = l[j + 1], l[j]
                swapped = True
        if not swapped:
            break
    return l
```

```python
def verifier_ip(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if not (0 <= int(part) <= 255):
            return False
    return True
```

```python
def freq_chars(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    return freq
```

```python
def convertir_octets(n):
    if n >= 1024**3:
        return f"{n / 1024**3:.2f} Go"
    elif n >= 1024**2:
        return f"{n / 1024**2:.2f} Mo"
    else:
        return f"{n / 1024:.2f} Ko"
```

